text = input()
freq = {}
for ch in text.lower():
    if ch.isalpha():
        freq[ch] = freq.get(ch, 0) + 1
for ch in sorted(freq.keys()):
    print(f"{ch}: {freq[ch]}")

def product_of_evens(*args):
    product = 1
    found_even = False
    for n in args:
        if n % 2 == 0:
            product *= n
            found_even = True
    return product if found_even else 1

nums = [int(x) for x in input().split()]
print(product_of_evens(*nums))

